Write-Host "=== ESET FULL SSL/TLS REGISTRY SCAN ==="; $sslKeywords = @("SSL","Tls","Filter","Ssl","Filt","SslFilter","SslTls","SslTlsFiltering","SslConfig","SslSettings","Inspection","Exclude","Exclusion","Network","Proxy","Intercept","Man-in-the-Middle","MITM","Encrypted","Certificate","RootCA","Root","CA","Trust","Verify","Enable","Disable","Active","Scan"); $basePaths = @("HKLM:\SOFTWARE\ESET\ESET Security","HKCU:\Software\ESET\ESET Security"); foreach ($base in $basePaths) { Write-Host "--- Scanning: $base ---" -ForegroundColor Cyan; Get-ChildItem $base -ErrorAction SilentlyContinue -Recurse -Depth 5 | ForEach-Object { $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue; if ($p) { $hits = $p.PSObject.Properties | Where-Object { $_.Name -in $sslKeywords }; if ($hits) { Write-Host "  FOUND in: $($_.Name)" -ForegroundColor Yellow; $hits | Format-Table Name,Value -AutoSize } } } }; Write-Host "---SCAN COMPLETE---"
